def traduire(texte, langue):
    if langue != 'en': return texte
    if texte in EN:return EN[texte]
    prefixes={'Prix d’achat · ':'Purchase price · ','Prix de vente HT · ':'Sale price excl. tax · ','Prix unitaire HT · ':'Unit price excl. tax · ','Montant · ':'Amount · ','Votre activité en ':'Your business in ','Recettes · ':'Income · ','Dépenses · ':'Expenses · ','CA annuel · ':'Annual turnover · ','CA année N−1 · ':'Previous turnover · ','Solde banque + caisse · ':'Bank and cash opening balance · ','Date du solde de départ · ':'Opening balance date · ','Brouillon enregistré · ':'Draft saved · ','Complétez la date au format ':'Complete the date in format ','Cette date n’existe pas. Utilisez ':'This date does not exist. Use ','Devis ':'Quote ','Reprise · ':'Opening balances · ','Version installée : ':'Installed version: ','Sauvegarde vérifiée : ':'Backup verified: '}
    for a,b in prefixes.items():
        if texte.startswith(a):return b+texte[len(a):]
    return texte


def tr(texte):return traduire(texte,ACTIVE)


def original(texte):
    if ACTIVE=='en':
        for key,value in EN.items():
            if value==texte:return key
    return texte
